from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
color_sensor_2 = ColorSensor(Port.E)
LeftMotor_2 = Motor(Port.A, Direction.COUNTERCLOCKWISE)
RightMotor_2 = Motor(Port.B, Direction.CLOCKWISE)
radhika_drive_base_2 = DriveBase(LeftMotor_2, RightMotor_2, 87, 120)


# The main program starts here.
while True:
    if color_sensor_2.reflection() > 20:
        radhika_drive_base_2.drive(200, 70)
    else:
        radhika_drive_base_2.drive(200, -70)
